-- TeknoVersus — Honor, General Mobile, TCL, Casper, Nubia marka genişletmesi (15 yeni telefon)
-- Supabase SQL Editor'de çalıştır. Ürünler eklendiği an products webhook'u otomatik build+deploy tetikler.
-- ÖNEMLİ: Bu SQL'i çalıştırmadan ÖNCE, ürün görsellerini (assets/products/*.png) ve urun/*.html
-- statik sayfalarını içeren güncellenmiş kodu GitHub'a push'lamış olman gerekiyor — aksi halde
-- otomatik build çalışsa da görseller sunucuda bulunmaz (404 kırık resim).

on conflict (id) do update set name=excluded.name, cat=excluded.cat, blurb=excluded.blurb, added_at=excluded.added_at, link=excluded.link, upcoming=excluded.upcoming, specs=excluded.specs, deleted=false;
